#include <iostream>
#include <vector>
#include <stdexcept>

void mover(int orden, int& x, int& y) {
    int propuestoX{x};
    int propuestoY{y};
    switch (orden) {
    case 1: ++propuestoX; break;
    case 2: --propuestoX; break;
    case 3: ++propuestoY; break;
    case 4: --propuestoY; break;
    default: throw std::invalid_argument{"Orden"};
    }
    if (propuestoX < 0 || propuestoX > 2 || propuestoY < 0 || propuestoY > 2) {
        throw std::out_of_range{"Tablero"};
    }
    x = propuestoX;
    y = propuestoY;
}

int main() {
    int x{0};
    int y{0};
    for (int orden : std::vector<int>{2, 1, 9, 3}) {
        try {
            mover(orden, x, y);
            std::cout << "A";
        } catch (const std::invalid_argument& error) {
            std::cout << "O";
        } catch (const std::out_of_range& error) {
            std::cout << "L";
        }
        std::cout << x << "," << y << ";";
    }
    return 0;
}

